import{_ as p,a0 as l,w as o,s as d,ao as c,I as i,x as s,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 at 命令在 Linux 上安排任务 | LCTT x X-CMD","titleTemplate":false,"description":"使用 at 命令在 Linux 上安排任务 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 at 命令在 Linux 上安排任务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 at 命令在 Linux 上安排任务 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200403 Scheduling tasks on Linux using the at command","title":"使用 at 命令在 Linux 上安排任务","tag":"202004","desc":""},"relativePath":"202004/20200403 Scheduling tasks on Linux using the at command.md","filePath":"[post].md"}'),r={name:"202004/20200403 Scheduling tasks on Linux using the at command.md"};function h(g,a,u,k,b,m){const n=l("Link");return o(),d("div",null,[a[15]||(a[15]=c(`<h1 id="使用-at-命令在-linux-上安排任务" tabindex="-1">使用 at 命令在 Linux 上安排任务 <a class="header-anchor" href="#使用-at-命令在-linux-上安排任务" aria-label="Permalink to “使用 at 命令在 Linux 上安排任务”">​</a></h1><blockquote><p>at 命令可以很容易地安排 Linux 任务在你选择的任何时间或日期运行，让我们来看看它能为你做什么。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/08/gettyimages-140389307-100808283-large.jpg" alt=""></p><p>当你希望命令或脚本在某个特定时间运行时，你不需要将手指放在键盘上盘旋等待按下回车键，或者是在特定时间坐在办公桌前。相反，你可以通过 <code>at</code> 命令来设置任务。在本文中，我们将研究如何使用 <code>at</code> 来安排任务，如何精确地选择任务希望运行的时间，以及如何使用 <code>at</code> 来查看安排运行的任务。</p><h3 id="at-vs-cron" tabindex="-1">at vs cron <a class="header-anchor" href="#at-vs-cron" aria-label="Permalink to “at vs cron”">​</a></h3><p>对于那些使用 cron 在 Linux 系统上安排任务的人来说，<code>at</code> 命令类似于 cron，因为你可以在选定的时间调度任务，但是 cron 用于定期运行的作业 —— 甚至是每年仅一次。大多数 cron 作业的频率都设置为每天、每周或每月运行一次，不过你可以控制运行的频率和时间。</p><p>另一方面，<code>at</code> 命令用于仅运行一次的任务。想在午夜重启系统？没问题，只要你有适当的权限，<code>at</code> 可以为你完成此操作。如果你希望系统在每个星期六凌晨 2 点重启，那么改用 cron。</p><h3 id="使用-at" tabindex="-1">使用 at <a class="header-anchor" href="#使用-at" aria-label="Permalink to “使用 at”">​</a></h3><p><code>at</code> 命令很容易使用，只需记住几件事。一个简单使用 <code>at</code> 的例子类似于这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 5:00PM</span></span>
<span class="line"><span>at&gt; date &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><p>在输入 <code>at</code> 和应该运行命令的时间，<code>at</code> 会提示你在设定时间会运行该命令（此例中是 <code>date</code> 命令）。输入 <code>^D</code>（<code>Ctrl + d</code>）来完成请求。</p><p>假设我们在下午 5 点之前设置这个 <code>at</code> 命令，那么这个日期和时间将在当天下午 5 点添加到名为 <code>thisfile</code> 文件的末尾。否则，该命令将在第二天下午 5 点运行。</p><p>与 <code>at</code> 命令进行交互时，可以输入多个命令。如果你要同时运行多个命令，只需输入多个命令行即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 6:22</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo first &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; echo second &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><p>在上面的命令中，我们使用了一个普通的用户账户，将一些简单的文本添加到该用户主目录的文件中。如果在上午 6:22 之后运行这些命令，那么命令会在第二天运行，因为 6:22 表示上午 6:22。如果你想在下午 6:22 运行，使用 <code>6:22 PM</code> 或者 <code>18:22</code>。<code>6:22 PM</code> 这样也是可以工作的。</p><p>你也可以通过使用 <code>at</code> 来安排命令在指定的日期或时间运行，例如 <code>10:00AM April 15 2021</code> 或 <code>noon + 5 days</code>（从今天起 5 天内的中午运行），以下是一些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>at 6PM tomorrow</span></span>
<span class="line"><span>at noon April 15 2021</span></span>
<span class="line"><span>at noon + 5 days</span></span>
<span class="line"><span>at 9:15 + 1000 days</span></span></code></pre></div><p>在指定要运行的命令并按下 <code>^D</code> 后，你会注意到 <code>at</code> 命令为每个请求分配了一个作业编号，这个数字将显示在 <code>at</code> 命令的作业队列中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at noon + 1000 days</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; date &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 36 at Tue Dec 27 12:00:00 2022        &lt;== job # is 36</span></span></code></pre></div><h3 id="检查队列" tabindex="-1">检查队列 <a class="header-anchor" href="#检查队列" aria-label="Permalink to “检查队列”">​</a></h3><p>你可以使用 <code>atq</code>（at queue）命令来查看 <code>at</code> 作业队列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atq</span></span>
<span class="line"><span>32      Thu Apr  2 03:06:00 2020 a shs</span></span>
<span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>34      Thu Apr  2 18:00:00 2020 a shs</span></span></code></pre></div><p>如果你需要取消队列中的一个作业，使用 <code>atrm</code>（at remove）命令和作业编号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atrm 32</span></span>
<span class="line"><span>$ atq</span></span>
<span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>34      Thu Apr  2 18:00:00 2020 a shs</span></span></code></pre></div><p>你可以使用 <code>at -c</code> 命令来查看安排任务的详细信息，其它详细信息（活动的搜索路径等）也可以看到，但是输出的最后一行将显示计划运行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at -c 36 | tail -6</span></span>
<span class="line"><span>cd /home/shs || {</span></span>
<span class="line"><span>         echo &#39;Execution directory inaccessible&#39; &gt;&amp;2</span></span>
<span class="line"><span>         exit 1</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>date &gt;&gt; thisfile</span></span></code></pre></div><p>注意，该命令显示首先会测试是否可以通过 <code>cd</code> 命令进入用户目录。如果不可以，作业将退出并显示错误。如果可以，则运行在 <code>at</code> 中指定的命令。它将命令视为 “进入 <code>/home/shs</code> 或退出并显示错误”。</p><h3 id="以-root-身份运行作业" tabindex="-1">以 root 身份运行作业 <a class="header-anchor" href="#以-root-身份运行作业" aria-label="Permalink to “以 root 身份运行作业”">​</a></h3><p>要以 root 身份运行 <code>at</code> 作业，只需将 <code>sudo</code> 与你的 <code>at</code> 命令一起使用，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo at 8PM</span></span>
<span class="line"><span>[sudo] password for shs:</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; reboot now</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 37 at Wed Apr  1 16:00:00 2020</span></span></code></pre></div><p>注意，root 的任务以 <code>root</code> 作为执行者显示在队列中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>37      Wed Apr  1 20:00:00 2020 a root         &lt;==</span></span></code></pre></div><h3 id="运行脚本" tabindex="-1">运行脚本 <a class="header-anchor" href="#运行脚本" aria-label="Permalink to “运行脚本”">​</a></h3><p>你还可以使用 <code>at</code> 命令来运行脚本，这里有一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 4:30PM</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; bin/tryme</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><h3 id="禁止使用-at-命令" tabindex="-1">禁止使用 at 命令 <a class="header-anchor" href="#禁止使用-at-命令" aria-label="Permalink to “禁止使用 at 命令”">​</a></h3><p><code>/etc/at.deny</code> 文件提供了一种禁止用户使用 <code>at</code> 命令的方法。默认情况下，它可能会包含一个不允许的账户列表，例如 <code>ftp</code> 和 <code>nobody</code>。可以使用 <code>/etc/at.allow</code> 文件执行相反的操作，但是通常只配置 <code>at.deny</code> 文件。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>当你要安排一项一次性任务时，无论你是希望在今天下午或几年后运行，<code>at</code> 命令都是通用且易于使用的。</p><hr>`,40)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3535808/scheduling-tasks-on-linux-using-the-at-command.html"},{default:t(()=>[...a[0]||(a[0]=[s("https://www.networkworld.com/article/3535808/scheduling-tasks-on-linux-using-the-at-command.html",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=s("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...a[2]||(a[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),a[7]||(a[7]=s(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[8]||(a[8]=s(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...a[4]||(a[4]=[s("MjSeven",-1)])]),_:1}),a[9]||(a[9]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...a[11]||(a[11]=[s("Linux中国",-1)])]),_:1}),a[14]||(a[14]=s(" 荣誉推出",-1))])])}const C=p(r,[["render",h]]);export{y as __pageData,C as default};
